CREATE TABLE ezcontentclass_attribute (id INT AUTO_INCREMENT NOT NULL, version INT DEFAULT 0 NOT NULL, can_translate INT DEFAULT 1, category VARCHAR(25) DEFAULT '' NOT NULL, contentclass_id INT DEFAULT 0 NOT NULL, data_float1 DOUBLE PRECISION DEFAULT NULL, data_float2 DOUBLE PRECISION DEFAULT NULL, data_float3 DOUBLE PRECISION DEFAULT NULL, data_float4 DOUBLE PRECISION DEFAULT NULL, data_int1 INT DEFAULT NULL, data_int2 INT DEFAULT NULL, data_int3 INT DEFAULT NULL, data_int4 INT DEFAULT NULL, data_text1 VARCHAR(255) DEFAULT NULL, data_text2 VARCHAR(50) DEFAULT NULL, data_text3 VARCHAR(50) DEFAULT NULL, data_text4 VARCHAR(255) DEFAULT NULL, data_text5 LONGTEXT DEFAULT NULL, data_type_string VARCHAR(50) DEFAULT '' NOT NULL, identifier VARCHAR(50) DEFAULT '' NOT NULL, is_information_collector INT DEFAULT 0 NOT NULL, is_required INT DEFAULT 0 NOT NULL, is_searchable INT DEFAULT 0 NOT NULL, is_thumbnail TINYINT(1) DEFAULT '0' NOT NULL, placement INT DEFAULT 0 NOT NULL, serialized_data_text LONGTEXT DEFAULT NULL, serialized_description_list LONGTEXT DEFAULT NULL, serialized_name_list LONGTEXT NOT NULL, INDEX ezcontentclass_attr_ccid (contentclass_id), INDEX ezcontentclass_attr_dts (data_type_string), PRIMARY KEY(id, version)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
